CREATE OR REPLACE FUNCTION public.public_profile(p_username text) RETURNS TABLE(id uuid,username text,display_name text,avatar_emoji text,avatar_color text,top_categories text[],followers integer,following integer,week_points integer,votes integer,i_follow boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.username,p.display_name,p.avatar_emoji,p.avatar_color,COALESCE((SELECT array_agg(category) FROM(SELECT q.category FROM public.votes v JOIN public.questions q ON q.id=v.question_id WHERE v.user_id=p.id GROUP BY q.category ORDER BY count(*) DESC,q.category LIMIT 3) t),p.interests[1:3]),(SELECT count(*)::int FROM public.follows f WHERE f.followee_id=p.id),(SELECT count(*)::int FROM public.follows f WHERE f.follower_id=p.id),COALESCE((SELECT sum(delta)::int FROM public.points_ledger l WHERE l.user_id=p.id AND l.reason IN ('vote','vote_interest','reaction','reaction_removed') AND l.created_at>now()-interval '7 days'),0),(SELECT count(*)::int FROM public.votes v WHERE v.user_id=p.id),EXISTS(SELECT 1 FROM public.follows f WHERE f.follower_id=auth.uid() AND f.followee_id=p.id) FROM public.profiles p WHERE lower(p.username)=lower(p_username) $$;
GRANT EXECUTE ON FUNCTION public.public_profile(text) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.leaderboard(p_category text,p_scope text DEFAULT 'all') RETURNS TABLE(user_id uuid,username text,display_name text,avatar_emoji text,avatar_color text,points integer) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.username,p.display_name,p.avatar_emoji,p.avatar_color,sum(l.delta)::int AS pts FROM public.points_ledger l JOIN public.profiles p ON p.id=l.user_id LEFT JOIN public.questions q ON q.id=l.question_id WHERE l.reason IN ('vote','vote_interest','reaction','reaction_removed') AND l.created_at>now()-interval '7 days' AND(p_category IS NULL OR q.category=p_category) AND(p_scope<>'following' OR p.id=auth.uid() OR EXISTS(SELECT 1 FROM public.follows f WHERE f.follower_id=auth.uid() AND f.followee_id=p.id)) GROUP BY p.id HAVING sum(l.delta)>0 ORDER BY pts DESC,p.username LIMIT 50 $$;
GRANT EXECUTE ON FUNCTION public.leaderboard(text,text) TO anon,authenticated;
ALTER TABLE public.questions ADD COLUMN kind text NOT NULL DEFAULT 'ab';
ALTER TABLE public.questions ADD COLUMN option_c_image text;
ALTER TABLE public.questions ADD COLUMN option_d_image text;
ALTER TABLE public.questions ADD CONSTRAINT questions_kind_check CHECK(kind IN ('ab','multi','buyskip'));
ALTER TABLE public.questions ADD CONSTRAINT questions_kind_photos_check CHECK((kind='multi' AND option_c_image IS NOT NULL) OR(kind<>'multi' AND option_c_image IS NULL AND option_d_image IS NULL));
ALTER TABLE public.questions DROP CONSTRAINT questions_decided_choice_check;
ALTER TABLE public.questions ADD CONSTRAINT questions_decided_choice_check CHECK(decided_choice IS NULL OR decided_choice IN ('a','b','c','d','neither'));
ALTER TABLE public.votes DROP CONSTRAINT votes_choice_check;
ALTER TABLE public.votes ADD CONSTRAINT votes_choice_check CHECK(choice IN ('a','b','c','d'));
ALTER TABLE public.comments DROP CONSTRAINT comments_choice_check;
ALTER TABLE public.comments ADD CONSTRAINT comments_choice_check CHECK(choice IN ('a','b','c','d'));
CREATE OR REPLACE FUNCTION public.question_has_choice(p_question uuid,p_choice text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.questions q WHERE q.id=p_question AND(p_choice IN ('a','b') OR(p_choice='c' AND q.option_c_image IS NOT NULL) OR(p_choice='d' AND q.option_d_image IS NOT NULL))) $$;
CREATE OR REPLACE FUNCTION public.ensure_vote_choice() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.question_has_choice(NEW.question_id,NEW.choice) THEN RAISE EXCEPTION 'Invalid choice for this question'; END IF; RETURN NEW; END $$;
REVOKE EXECUTE ON FUNCTION public.ensure_vote_choice() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER votes_valid_choice BEFORE INSERT ON public.votes FOR EACH ROW EXECUTE FUNCTION public.ensure_vote_choice();
CREATE OR REPLACE FUNCTION public.decide_question(p_question uuid,p_choice text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF p_choice<>'neither' AND NOT public.question_has_choice(p_question,p_choice) THEN RAISE EXCEPTION 'Invalid choice'; END IF; UPDATE public.questions SET decided_choice=p_choice,decided_at=now(),ends_at=LEAST(COALESCE(ends_at,now()),now()) WHERE id=p_question AND user_id=auth.uid(); IF NOT FOUND THEN RAISE EXCEPTION 'Question not found'; END IF; END $$;
REVOKE EXECUTE ON FUNCTION public.decide_question(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.decide_question(uuid,text) TO authenticated;